WF.add({
  id: "ps-gewohnheiten", cat: "psychologie", min: 6, wiki: "Gewohnheit", tags: ["Habits", "Dopamin", "Atomic Habits", "Motivation", "Social Media"],
  title: "Wie Gewohnheiten funktionieren",
  hook: "Fast die Hälfte deines Tages läuft auf Autopilot. Hier lernst du, wie du den Autopiloten umprogrammierst, und warum TikTok so gut darin ist.",
  cards: [
    { h: "Dein Autopilot", t: "Die Psychologin **Wendy Wood** ließ Studierende über den Tag protokollieren, was sie gerade tun. Ergebnis: Rund **40 Prozent** ihrer Handlungen waren **Gewohnheiten**, also Dinge, die sie fast jeden Tag am selben Ort taten, während sie an etwas anderes dachten.\n\nGewohnheiten werden in einem tiefliegenden Hirnbereich gespeichert, den **Basalganglien**. Das ist praktisch: Zähneputzen, Autofahren oder die Tastatur bedienen kosten kaum Denkkraft. Das Gehirn spart Energie für Neues. Der Nachteil: Schlechte Gewohnheiten laufen genauso automatisch ab wie gute.", merke: "Etwa 40 Prozent unserer täglichen Handlungen sind Gewohnheiten." },
    { h: "Die Gewohnheitsschleife", t: "Jede Gewohnheit folgt einer **Schleife** aus drei Teilen, beschrieben etwa vom Journalisten Charles Duhigg:\n\n1. **Auslöser**: ein Reiz, der das Verhalten startet. Langeweile, eine Uhrzeit, ein Ort, eine Benachrichtigung.\n2. **Routine**: das Verhalten selbst. Zum Handy greifen.\n3. **Belohnung**: das gute Gefühl danach. Ein lustiges Video, ein neues Like.\n\nJe öfter die Schleife durchlaufen wird, desto stärker verbindet das Gehirn Auslöser und Belohnung. Irgendwann reicht der Auslöser allein, und die Hand greift zum Handy, bevor du überhaupt entschieden hast.", merke: "Gewohnheiten bestehen aus Auslöser, Routine und Belohnung." },
    { h: "Warum Scrollen so schwer aufzuhören ist", t: "Der Botenstoff **Dopamin** wird oft „Glückshormon“ genannt. Genauer gesagt steuert er aber **Erwartung und Motivation**: Er wird besonders stark ausgeschüttet, wenn wir eine Belohnung erwarten, und wenn sie **überraschend** kommt.\n\nSchon in den 1950er Jahren zeigte der Psychologe **B. F. Skinner** an Tauben: Am hartnäckigsten picken die Tiere, wenn es **unvorhersehbar** mal Futter gibt und mal nicht. Diese **variable Belohnung** ist das Prinzip von Spielautomaten. Und von endlosen Feeds: Das nächste Video könnte langweilig sein oder genial. Genau diese Ungewissheit hält dich beim Scrollen.", merke: "Unvorhersehbare Belohnungen machen Verhalten besonders hartnäckig, wie bei Spielautomaten und Feeds.",
      check: { q: "Warum fesseln endlose Video-Feeds so stark?", o: ["Weil die Belohnung unvorhersehbar ist, wie bei einem Spielautomaten", "Weil jedes Video gleich gut ist", "Weil sie wenig Strom verbrauchen"], a: 0, e: "Variable Belohnungen sorgen für besonders starke Dopamin-Erwartung." } },
    { h: "Der 21-Tage-Mythos", t: "Oft hört man, eine neue Gewohnheit brauche **21 Tage**. Diese Zahl geht auf Beobachtungen eines Schönheitschirurgen in den 1960ern zurück und wurde nie wissenschaftlich belegt.\n\nEine Studie von **Phillippa Lally** am University College London von 2009 ergab: Bis eine neue Gewohnheit automatisch läuft, dauert es im Durchschnitt **66 Tage**, je nach Person und Verhalten zwischen **18 und 254 Tagen**. Ein Glas Wasser zum Frühstück geht schneller als 50 Liegestütze. Die gute Nachricht aus derselben Studie: **Einzelne verpasste Tage** schadeten dem Aufbau der Gewohnheit kaum.", merke: "Neue Gewohnheiten brauchen im Schnitt 66 Tage, nicht 21." },
    { h: "Gewohnheiten umbauen", t: "**James Clear** fasst in **„Atomic Habits“** vier Gesetze zusammen. Für eine gute Gewohnheit gilt: Mach sie **offensichtlich**, **attraktiv**, **einfach** und **befriedigend**. Für eine schlechte gilt das Gegenteil: unsichtbar, unattraktiv, schwierig, unbefriedigend.\n\nPraktisch heißt das: Leg das Buch aufs Kopfkissen und die Gitarre in die Mitte des Zimmers. Verschieb die TikTok-App in einen Ordner auf der letzten Seite oder melde dich ab, damit jeder Zugriff mühsam wird. Nutze die **Zwei-Minuten-Regel**: Starte so klein, dass es weniger als zwei Minuten dauert, etwa „eine Lektion öffnen“. Und hänge Neues an Bestehendes: „Nach dem Frühstück mache ich meine Tageslektion.“", merke: "Gute Gewohnheiten: offensichtlich, attraktiv, einfach, befriedigend." },
  ],
  quiz: [
    { t: "order", q: "Bring die Teile der Gewohnheitsschleife in Reihenfolge.", o: ["Auslöser", "Routine", "Belohnung"], e: "Zum Beispiel: Langeweile, zum Handy greifen, lustiges Video." },
    { t: "tf", q: "Wissenschaftlich belegt braucht jede Gewohnheit genau 21 Tage.", a: false, e: "Im Schnitt sind es eher 66 Tage, mit großer Spanne von 18 bis 254 Tagen." },
    { t: "mc", q: "Wofür ist Dopamin vor allem zuständig?", o: ["Für Schmerzempfinden", "Für Erwartung und Motivation", "Für die Verdauung", "Für das Einschlafen"], a: 1, e: "Dopamin treibt uns an, eine erwartete Belohnung zu holen." },
    { t: "gap", q: "Nach der ___-Minuten-Regel sollte eine neue Gewohnheit anfangs ganz klein sein.", a: ["Zwei", "2"], e: "Wer klein startet, scheitert seltener am inneren Widerstand." },
    { t: "match", q: "Wie machst du eine gute Gewohnheit leicht und eine schlechte schwer?", pairs: [["Gute Gewohnheit", "Offensichtlich und einfach machen"], ["Schlechte Gewohnheit", "Unsichtbar und schwierig machen"], ["Gewohnheiten stapeln", "Neues an Bestehendes hängen"]], e: "Umgebung schlägt Willenskraft." },
  ],
  tips: ["Buch: James Clear, „Die 1%-Methode“ (Atomic Habits auf Deutsch). Eines der praktischsten Bücher zu dem Thema.", "Experiment: Schalte für eine Woche alle Push-Benachrichtigungen außer Anrufen und Nachrichten aus. Beobachte, wie oft du trotzdem zum Handy greifst.", "Leg Wissensfunke als Lesezeichen genau dort ab, wo bisher TikTok auf deinem Startbildschirm lag."],
  fact: "Die Tauben in Skinners Experimenten pickten bei unvorhersehbaren Belohnungen teils **tausende Male** hintereinander, obwohl nur selten Futter kam.",
});

WF.add({
  id: "ps-gedaechtnis", cat: "psychologie", min: 7, wiki: "Gedächtnis", tags: ["Lernen", "Vergessen", "Ebbinghaus", "Hippocampus", "Erinnerung"],
  title: "Wie dein Gedächtnis funktioniert",
  hook: "Warum du Namen sofort vergisst, aber Liedtexte von vor zehn Jahren kannst, und warum deine Erinnerungen dich anlügen.",
  cards: [
    { h: "Drei Speicher", t: "Psychologen unterscheiden grob drei Gedächtnisstufen. Das **sensorische Gedächtnis** hält Eindrücke nur für Bruchteile von Sekunden, etwa das Bild, das du gerade gesehen hast. Was du beachtest, kommt ins **Arbeitsgedächtnis**. Es ist erstaunlich klein: Heutige Forschung geht von etwa **vier Informationseinheiten** gleichzeitig aus.\n\nDeshalb merkst du dir eine Telefonnummer leichter in Gruppen: 0176 / 482 / 93 / 15 statt 017648293 15. Das nennt man **Chunking**. Was du wiederholst und mit Bedeutung verknüpfst, gelangt schließlich ins **Langzeitgedächtnis**, dessen Kapazität praktisch unbegrenzt ist.", merke: "Das Arbeitsgedächtnis fasst nur etwa vier Einheiten. Chunking hilft." },
    { h: "Die Vergessenskurve", t: "Der deutsche Psychologe **Hermann Ebbinghaus** machte 1885 ein mühsames Selbstexperiment. Er lernte Listen sinnloser Silben wie „DAX“ oder „BOK“ auswendig und testete, wie viel er nach Minuten, Stunden und Tagen noch wusste.\n\nDas Ergebnis ist die **Vergessenskurve**: Direkt nach dem Lernen vergessen wir sehr schnell, danach flacht der Verlust ab. Ohne Wiederholung ist nach einem Tag bereits ein Großteil weg. Ebbinghaus entdeckte aber auch: Mit jeder **Wiederholung** wird die Kurve flacher. Wer in wachsenden Abständen wiederholt, behält dauerhaft. Das nennt man **verteiltes Lernen** oder **Spaced Repetition**, und genau so arbeitet der Wiederholen-Tab dieser App.", merke: "Ohne Wiederholung vergessen wir schnell. Verteiltes Wiederholen macht Wissen dauerhaft." },
    { h: "Der Mann, der nichts Neues behielt", t: "1953 entfernten Chirurgen dem jungen **Henry Molaison** wegen schwerer Epilepsie Teile beider Schläfenlappen, darunter große Teile des **Hippocampus**. Die Anfälle wurden besser, doch es geschah etwas Unerwartetes: Henry konnte **keine neuen Langzeiterinnerungen** mehr bilden.\n\nEr erkannte Ärzte nicht wieder, die er seit Jahren täglich sah. Ältere Erinnerungen aus seiner Kindheit waren aber da. Und er konnte **neue Bewegungen** lernen, etwa Zeichnen im Spiegel, ohne sich ans Üben zu erinnern. In der Forschung als **Patient H. M.** bekannt, zeigte er: Es gibt verschiedene Gedächtnissysteme, und der Hippocampus ist das Tor ins Langzeitgedächtnis für Fakten und Erlebnisse.", merke: "Der Hippocampus ist entscheidend, um neue Fakten und Erlebnisse dauerhaft zu speichern.",
      check: { q: "Was konnte Patient H. M. nach der Operation nicht mehr?", o: ["Neue Fakten und Erlebnisse dauerhaft speichern", "Sprechen", "Sich an seine Kindheit erinnern"], a: 0, e: "Alte Erinnerungen und motorisches Lernen funktionierten weiter. Nur neue bewusste Erinnerungen fehlten." } },
    { h: "Erinnerungen werden neu gebaut", t: "Unser Gedächtnis ist **keine Videokamera**. Jedes Mal, wenn wir uns erinnern, wird die Erinnerung **neu zusammengesetzt** und kann sich dabei verändern.\n\nDie Psychologin **Elizabeth Loftus** zeigte Versuchspersonen in den 1970er Jahren Filme von Autounfällen. Fragte sie, wie schnell die Autos waren, als sie **„ineinander krachten“**, schätzten die Leute höhere Geschwindigkeiten als bei der Frage, wie schnell sie waren, als sie sich **„berührten“**. Eine Woche später erinnerten sich mehr Menschen aus der Krachen-Gruppe an **Glasscherben**, obwohl es keine gab. Loftus' Forschung veränderte, wie Gerichte Zeugenaussagen bewerten.", merke: "Erinnerungen werden bei jedem Abruf neu gebaut und können verfälscht werden." },
    { h: "So lernst du mit deinem Gehirn statt gegen es", t: "Aus der Gedächtnisforschung lassen sich klare Regeln ableiten:\n\n**Abrufen statt Wiederlesen**: Sich selbst zu testen ist eine der wirksamsten Lernmethoden. Forscher nennen das den **Testeffekt**. Genau deshalb hat jede Lektion hier ein Quiz.\n\n**Verteilen statt Pauken**: Dreimal 20 Minuten an verschiedenen Tagen schlagen eine Stunde am Stück.\n\n**Verknüpfen**: Neues mit Bekanntem, Bildern und Gefühlen verbinden. Das Gehirn merkt sich Geschichten besser als Listen.\n\n**Schlafen**: Im Schlaf wird Gelerntes gefestigt. Wer nach dem Lernen gut schläft, erinnert sich besser.", merke: "Abrufen, verteilen, verknüpfen, schlafen: die vier Regeln für ein gutes Gedächtnis." },
  ],
  quiz: [
    { t: "mc", q: "Wie viele Informationseinheiten fasst das Arbeitsgedächtnis nach heutiger Forschung ungefähr?", o: ["Etwa 4", "Etwa 20", "Etwa 100", "Unbegrenzt"], a: 0, e: "Ältere Lehrbücher nennen „7 plus minus 2“, neuere Studien gehen eher von etwa vier aus." },
    { t: "gap", q: "Die Vergessenskurve geht auf den Psychologen Hermann ___ zurück.", a: ["Ebbinghaus"], e: "Er testete 1885 an sich selbst, wie schnell er sinnlose Silben vergaß." },
    { t: "tf", q: "Unser Gedächtnis speichert Erlebnisse wie eine Videokamera unverändert ab.", a: false, e: "Erinnerungen werden bei jedem Abruf neu zusammengesetzt und können sich verändern." },
    { t: "match", q: "Ordne zu.", pairs: [["Hippocampus", "Tor zum Langzeitgedächtnis"], ["Chunking", "Informationen in Gruppen bündeln"], ["Testeffekt", "Abrufen festigt Wissen"], ["Elizabeth Loftus", "Falsche Erinnerungen"]], e: "Diese Begriffe helfen dir, dein eigenes Lernen zu verstehen." },
    { t: "mc", q: "Welche Lernstrategie ist laut Forschung besonders wirksam?", o: ["Den Text mehrfach durchlesen", "Sich selbst abfragen", "Alles in einer Nacht pauken", "Mit Musik im Hintergrund markieren"], a: 1, e: "Aktives Abrufen, der Testeffekt, schlägt passives Wiederlesen deutlich." },
  ],
  tips: ["Probier die Loci-Methode: Merk dir eine Einkaufsliste, indem du jeden Artikel gedanklich in einen Raum deiner Wohnung legst.", "Buch: Joshua Foer, „Moonwalk mit Einstein“, über einen Journalisten, der in einem Jahr zum Gedächtnismeister wurde.", "Mach heute Abend vor dem Schlafen eine kurze Wiederholungsrunde. Morgen früh weißt du mehr als gedacht."],
  fact: "Der Journalist Joshua Foer trainierte nur ein Jahr und gewann 2006 die **US-Gedächtnismeisterschaft**, unter anderem durch Merken eines Kartenstapels in unter zwei Minuten.",
});

